import com.minecolonies.core.network.messages.server.AbstractBuildingServerMessage;
import net.minecraft.network.FriendlyByteBuf;
import net.minecraftforge.common.capabilities.ForgeCapabilities;
import net.minecraftforge.network.NetworkEvent;

public class SortBuildingMessage
extends AbstractBuildingServerMessage<IBuilding> {
    public SortBuildingMessage() {
    }

    public SortBuildingMessage(IBuildingView building) {
        super(building);
    }

    @Override
    protected void toBytesOverride(FriendlyByteBuf buf) {
    }

    @Override
    protected void fromBytesOverride(FriendlyByteBuf buf) {
    }

    @Override
    protected void onExecute(NetworkEvent.Context ctxIn, boolean isLogicalServer, IColony colony, IBuilding building) {
        if (building.canSort()) {
            building.getCapability(ForgeCapabilities.ITEM_HANDLER, null).ifPresent(inv -> building.sort((CombinedItemHandler)inv));
        }
    }
}

